"""Kaggle runner: Baseline 2 generative return OOS (Beta Seg155, dual T4).

Zero training. Eval-only kernel — does NOT overwrite dual-T4 training notebook.
Decode recipe locked a priori to C2 spirit (see evaluate_beta_v21_generative_return_oos).
"""

from __future__ import annotations

import base64
import gc
import io
import json
import os
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

EMBEDDED_KRONOS_ARCHIVE_B64 = """

"""

OUTPUT_NAME = "beta_v2_1_c1_gen_return_oos"
EXPERIMENT_NAME = "beta_v2_1_c1_gen_return_oos"
MODEL_REPO = "luckfu/Kronos-A-Share-Beta-V2-1"
EXPECTED_TOKENIZER_SHA256 = (
    "59d85f6af76a2c3b8240ea06cb21db4213b4eeca053f246b23e29cf832fc6bee"
)
EXPECTED_SEG155_SHA256 = (
    "8b11a759e72d4125cb0c3307c482f1931ddc65be612023b422d66c52e4f8609c"
)
EXPECTED_EVAL_NAME = "kronos_beta_v2_time_oos_through_20260903"
EXPECTED_SIGNAL_DATES = 18
EXPECTED_SAMPLES = 92751
WORLD_SIZE = 2
HARD_LIMIT_SECONDS = 39600
EFFECTIVE_BATCH = 256  # flattened items*N per AR step; T4 16GB is ample (C2 small used 64)

CHECKPOINT = (
    "seg155_forecast_best",
    (
        "**/kronos-beta-v21-c1-seg155-forecast-best/**/checkpoints/best_model",
        "**/kronos-beta-v21-c1-seg155-forecast-best/checkpoints/best_model",
    ),
)


def emit(message: str) -> None:
    line = str(message)
    print(line, flush=True)
    log = Path("/kaggle/working") / OUTPUT_NAME / "run.log"
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a", buffering=1) as handle:
        handle.write(line + "\n")


def sha256_file(path: Path) -> str:
    import hashlib

    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def extract_bundle(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    raw = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as archive:
        archive.extractall(target)
    root = target / "Kronos"
    if not (root / "model").is_dir():
        raise RuntimeError(f"Embedded archive missing model/ under {root}")
    return root


def download_tokenizer(target: Path) -> Path:
    target.mkdir(parents=True, exist_ok=True)
    try:
        from modelscope.hub.snapshot_download import snapshot_download
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "-q", "modelscope"]
        )
        from modelscope.hub.snapshot_download import snapshot_download
    emit(f"phase=download_tokenizer repo={MODEL_REPO}")
    snapshot_download(MODEL_REPO, local_dir=str(target))
    tokenizer = target / "tokenizer"
    if not (tokenizer / "config.json").is_file():
        matches = list(target.glob("**/tokenizer/config.json"))
        if not matches:
            raise RuntimeError(f"Tokenizer not found under {target}")
        tokenizer = matches[0].parent
    tok_sha = sha256_file(tokenizer / "model.safetensors")
    emit(f"phase=tokenizer_ready path={tokenizer} sha256={tok_sha}")
    if tok_sha != EXPECTED_TOKENIZER_SHA256:
        raise RuntimeError(
            f"Tokenizer SHA mismatch: {tok_sha} != {EXPECTED_TOKENIZER_SHA256}"
        )
    return tokenizer


def find_checkpoint(input_root: Path, label: str, patterns: tuple[str, ...]) -> Path:
    matches = []
    for pattern in patterns:
        for path in input_root.glob(pattern):
            if (path / "config.json").is_file() and (
                (path / "model.safetensors").is_file()
                or (path / "pytorch_model.bin").is_file()
            ):
                matches.append(path.resolve())
    matches = sorted(set(matches))
    if len(matches) != 1:
        raise RuntimeError(f"{label}: expected one checkpoint, found {matches}")
    emit(f"phase=checkpoint label={label} path={matches[0]}")
    return matches[0]


def parent_main() -> None:
    started = time.time()
    working = Path("/kaggle/working") / OUTPUT_NAME
    working.mkdir(parents=True, exist_ok=True)
    shards = working / "shards"
    shards.mkdir(exist_ok=True)
    results = working / "results"
    results.mkdir(exist_ok=True)

    gpu_names = subprocess.check_output(
        ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"], text=True
    ).strip().splitlines()
    if len(gpu_names) != WORLD_SIZE or any("T4" not in name for name in gpu_names):
        raise RuntimeError(f"Expected exactly two Tesla T4 GPUs, found {gpu_names}")
    emit(f"phase=start experiment={EXPERIMENT_NAME}")
    emit("phase=gpu\n" + "\n".join(gpu_names))

    repo = extract_bundle(working / "src")
    sys.path.insert(0, str(repo))
    sys.path.insert(0, str(repo / "finetune"))

    from evaluate_beta_v21_generative_return_oos import (
        ARMS,
        REFERENCE,
        build_summary,
        score_predictions,
    )
    from evaluate_beta_v21_time_oos import find_evaluation_root, load_incremental_records
    import pandas as pd

    tokenizer = download_tokenizer(working / "pretrained")
    input_root = Path("/kaggle/input")
    label, patterns = CHECKPOINT
    checkpoint_dir = find_checkpoint(input_root, label, patterns)
    weights = checkpoint_dir / "model.safetensors"
    model_sha = sha256_file(weights)
    if model_sha != EXPECTED_SEG155_SHA256:
        raise RuntimeError(
            f"Seg155 SHA mismatch: {model_sha} != {EXPECTED_SEG155_SHA256}"
        )
    emit(f"phase=seg155_sha_ok sha256={model_sha}")

    evaluation_root, manifest = find_evaluation_root(input_root)
    samples_path = evaluation_root / manifest["artifacts"]["samples_file"]
    records = load_incremental_records(samples_path, manifest)
    dates = sorted({row["asof_date"] for row in records})
    if len(dates) != EXPECTED_SIGNAL_DATES or len(records) != EXPECTED_SAMPLES:
        raise RuntimeError(
            f"Expected {EXPECTED_SIGNAL_DATES} dates / {EXPECTED_SAMPLES} samples, "
            f"found {len(dates)} / {len(records)}"
        )
    if manifest.get("name") != EXPECTED_EVAL_NAME:
        raise RuntimeError(f"Unexpected eval name: {manifest.get('name')}")

    # prod (N=5) first for an early read; ranking N=16 second. Arm-major order
    # with (arm, date) round-robin so the first arm completes before the second.
    tasks = [{"arm": arm["name"], "date": date} for arm in ARMS for date in dates]
    plan_path = working / "plan.json"
    plan = {
        "repo": str(repo),
        "tokenizer_dir": str(tokenizer),
        "checkpoint_dir": str(checkpoint_dir),
        "checkpoint_label": label,
        "evaluation_root": str(evaluation_root),
        "shards": str(shards),
        "deadline": started + HARD_LIMIT_SECONDS,
        "effective_batch": EFFECTIVE_BATCH,
        "tasks": tasks,
        "score_definition": (
            "predicted_return_d10 = mean_N AR samples of "
            "(denorm_close_d10 / last_close - 1); NOT return_head; NOT teacher-forcing"
        ),
        "arms": ARMS,
        "reference": REFERENCE,
    }
    plan_path.write_text(json.dumps(plan, ensure_ascii=False, indent=2) + "\n")
    emit(
        json.dumps(
            {
                "phase": "inputs_resolved",
                "evaluation_name": EXPECTED_EVAL_NAME,
                "checkpoint": label,
                "model_sha256": model_sha,
                "signal_dates": len(dates),
                "records": len(records),
                "arms": [arm["name"] for arm in ARMS],
                "tasks": len(tasks),
                "effective_batch": EFFECTIVE_BATCH,
                "training": False,
            },
            ensure_ascii=False,
        )
    )

    worker_script = repo / "finetune" / "evaluate_beta_v21_generative_return_oos.py"
    processes = []
    for rank in range(WORLD_SIZE):
        environment = os.environ.copy()
        environment.update(
            {
                "PYTHONUNBUFFERED": "1",
                "CUDA_VISIBLE_DEVICES": str(rank),
                "KRONOS_SWEEP_RANK": str(rank),
                "KRONOS_SWEEP_WORLD": str(WORLD_SIZE),
                "PYTHONPATH": os.pathsep.join(
                    [str(repo), str(repo / "finetune"), environment.get("PYTHONPATH", "")]
                ),
            }
        )
        processes.append(
            subprocess.Popen(
                [sys.executable, "-u", str(worker_script), "--worker-plan", str(plan_path)],
                env=environment,
            )
        )
    emit(f"phase=workers_spawned n={WORLD_SIZE} script={worker_script}")
    failures = [process.wait() for process in processes]
    if any(code != 0 for code in failures):
        raise RuntimeError(f"Worker exit codes: {failures}")

    summaries = []
    incomplete = []
    for arm in ARMS:
        parts = sorted(shards.glob(f"{arm['name']}_*.csv.gz"))
        if len(parts) != len(dates):
            incomplete.append(
                {"arm": arm["name"], "have": len(parts), "need": len(dates)}
            )
            continue
        frame = pd.concat([pd.read_csv(path) for path in parts], ignore_index=True)
        if len(frame) != len(records):
            raise RuntimeError(
                f"{arm['name']} row mismatch: {len(frame)} != {len(records)}"
            )
        metrics = score_predictions(frame)
        summary = build_summary(
            label,
            checkpoint_dir,
            arm,
            metrics,
            seconds=time.time() - started,
            use_aux=False,
            model_sha=model_sha,
        )
        summaries.append(summary)
        stem = f"{label}_{arm['name']}"
        frame.to_csv(
            results / f"{stem}_predictions.csv.gz", index=False, compression="gzip"
        )
        (results / f"{stem}_summary.json").write_text(
            json.dumps(summary, ensure_ascii=False, indent=2) + "\n"
        )
        emit(
            json.dumps(
                {
                    "phase": "arm_scored",
                    "arm": arm["name"],
                    "return10d_rank_ic_daily": summary["return10d_rank_ic_daily"],
                    "utility_rank_ic_daily": summary["utility_rank_ic_daily"],
                    "pairwise_accuracy": summary["pairwise_accuracy"],
                    "vs_c2": summary["vs_c2_rank_return10d_ic"],
                    "vs_seg19_return_head": summary["vs_seg19_return_head_return10d_ic"],
                },
                ensure_ascii=False,
            )
        )

    comparison = {
        "evaluation_name": EXPECTED_EVAL_NAME,
        "baseline": "baseline_2_generative_return",
        "training": False,
        "checkpoint": label,
        "model_sha256": model_sha,
        "score_definition": plan["score_definition"],
        "arms": [arm["name"] for arm in ARMS],
        "checkpoints": summaries,
        "incomplete": incomplete,
        "reference": REFERENCE,
        "elapsed_sec": time.time() - started,
        "kernel": "luckfu/kronos-beta-v21-c1-gen-return-oos",
    }
    (results / "comparison.json").write_text(
        json.dumps(comparison, ensure_ascii=False, indent=2) + "\n"
    )
    shutil.copy2(results / "comparison.json", working / "comparison.json")
    emit("phase=comparison\n" + json.dumps(comparison, ensure_ascii=False, indent=2)[:6000])
    if not summaries:
        raise RuntimeError(f"No arm completed: {incomplete}")
    if incomplete:
        emit(f"phase=partial incomplete={json.dumps(incomplete)}")
    emit(f"phase=done total_seconds={time.time()-started:.1f}")


def main() -> None:
    parent_main()


if __name__ == "__main__":
    main()
